function check(candidate) {
    console.assert(JSON.stringify(candidate([1,2,3,4], [4,3,2,1])) === JSON.stringify([1, 2, 3, 4]));
    console.assert(JSON.stringify(candidate([1,1,1,1], [1,1,1,1])) === JSON.stringify([1]));
    console.assert(JSON.stringify(candidate([1,3,5,7], [2,4,6,8])) === JSON.stringify([]));
    console.assert(JSON.stringify(candidate([0,0,0,0], [0,0,0,0])) === JSON.stringify([0]));
    console.assert(JSON.stringify(candidate([0,1,2,3,4,5], [5,4,3,2,1,0])) === JSON.stringify([0, 1, 2, 3, 4, 5]));
    console.assert(JSON.stringify(candidate([10,20,30,40], [30,40,50,60])) === JSON.stringify([40, 30]));
    console.assert(JSON.stringify(candidate([1000], [1000])) === JSON.stringify([1000]));
    console.assert(JSON.stringify(candidate([1,2,3,4,5], [5,4,3,2,1])) === JSON.stringify([1, 2, 3, 4, 5]));
    console.assert(JSON.stringify(candidate([1,2,2,1], [2,2])) === JSON.stringify([2]));
    console.assert(JSON.stringify(candidate([1000,1000,1000], [1000,1000])) === JSON.stringify([1000]));
    console.assert(JSON.stringify(candidate([10,20,30], [30,40,50])) === JSON.stringify([30]));
    console.assert(JSON.stringify(candidate([5,5,5,5], [5,5,5,5])) === JSON.stringify([5]));
    console.assert(JSON.stringify(candidate([4,9,5], [9,4,9,8,4])) === JSON.stringify([9, 4]));
    console.assert(JSON.stringify(candidate([0,1000], [500,1000])) === JSON.stringify([1000]));
    console.assert(JSON.stringify(candidate([1,2,3], [4,5,6])) === JSON.stringify([]));
    console.assert(JSON.stringify(candidate([1000,1000], [1000,1000])) === JSON.stringify([1000]));
    console.assert(JSON.stringify(candidate([500,500,500], [500])) === JSON.stringify([500]));
